from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Sw_update(EmssimCommand):
    def __init__(self, method="sw_update", timeout=2100, rpc_connection_name='localRPC'):
        super(Sw_update, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Sw_update, self).on_new_data(**data)
        if 'msg' in data:
            if data['msg'] == "Starting Software Update Operation":
                self._ret['sw_build'] = data['SW_Build']
                self._ret['TargetBD_file'] = data['TargetBD_file']
            elif data['msg'] == "Validation completed, activating plan file":
                self._ret['validation'] = "completed"
            elif data['msg'] == "Activation completed":
                self._ret['activation'] = "completed"
        elif 'status' in data:
            self._ret['status'] = data['status']
